// The compiler throws an error if the function is provided a `name` option which is not a string...
{
	new Scale( { 'name': 5 } ); // $ExpectError
	new Scale( { 'name': true } ); // $ExpectError
	new Scale( { 'name': false } ); // $ExpectError
	new Scale( { 'name': null } ); // $ExpectError
	new Scale( { 'name': [] } ); // $ExpectError
	new Scale( { 'name': {} } ); // $ExpectError
	new Scale( { 'name': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `range` option which is not a collection, an object, or a string...
{
	new Scale( { 'name': 'xScale', 'range': 5 } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'range': true } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'range': false } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'range': null } ); // $ExpectError
}

