// The compiler throws an error if the function is provided a `type` option which is not a supported scale type...
{
	new Scale( { 'name': 'xScale', 'type': '5' } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': 5 } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': true } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': false } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': null } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': [] } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': {} } ); // $ExpectError
	new Scale( { 'name': 'xScale', 'type': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided more than one argument...
{
	new Scale( { 'name': 'xScale' }, {} ); // $ExpectError
	Scale( { 'name': 'xScale' }, {} ); // $ExpectError
}

// A scale instance has scale properties...
{
	const scale = new Scale( { 'name': 'xScale' } );

	const domain = scale.domain; // $ExpectType object | Collection<any> | undefined
	const domainMax = scale.domainMax; // $ExpectType number | undefined
	const domainMin = scale.domainMin; // $ExpectType number | undefined
	const domainMid = scale.domainMid; // $ExpectType number | undefined
	const domainRaw = scale.domainRaw; // $ExpectType Collection<any> | undefined
	const interpolate = scale.interpolate; // $ExpectType object | InterpolationMethod | undefined
	const name = scale.name; // $ExpectType string
	const range = scale.range; // $ExpectType string | object | Collection<any> | undefined
	const reverse = scale.reverse; // $ExpectType boolean
	const round = scale.round; // $ExpectType boolean
	const type = scale.type; // $ExpectType ScaleType

	const values = [
		domain,
		domainMax,
		domainMin,
		domainMid,
		domainRaw,
		interpolate,
		name,
		range,
		reverse,
		round,
		type
	];
	if ( values.length !== 11 ) {
		throw new Error( 'unexpected error' );
	}
}

// The compiler throws an error if a scale property is assigned an unsupported value...
{
	const scale = new Scale( { 'name': 'xScale' } );

	scale.domain = 5; // $ExpectError
	scale.domainMax = '5'; // $ExpectError
	scale.name = 5; // $ExpectError
	scale.reverse = '5'; // $ExpectError
	scale.type = 'abc'; // $ExpectError
}

// A scale instance has a read-only `properties` property...
{
	const scale = new Scale( { 'name': 'xScale' } );

	const props = scale.properties; // $ExpectType string[]
	if ( props.length !== 11 ) {
		throw new Error( 'unexpected error' );
	}
	scale.properties = [ 'name' ]; // $ExpectError
}

// A scale instance has a `toJSON` method which returns a JSON object...
{
	const scale = new Scale( { 'name': 'xScale' } );

	scale.toJSON(); // $ExpectType JSON
}

// The compiler throws an error if the `toJSON` method is provided arguments...
{
	const scale = new Scale( { 'name': 'xScale' } );

	scale.toJSON( {} ); // $ExpectError
}
